package com.kitchenos.connect.ui;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import com.kitchenos.common.Ui;import com.kitchenos.connect.kitchen.*;import org.json.JSONObject;
/** An acknowledged append with a stable outbox retry; closing never claims cancellation. */
public final class SharedPlanDialog {
 public interface Write {JSONObject add(JSONObject card,String date,int portions)throws Exception;}
 public static AlertDialog show(Activity activity,JSONObject card,int portions,Runnable complete){return show(activity,card,portions,(recipe,date,count)->new KalomatikPlanWriter(activity).add(recipe,date,count),complete);}
 public static AlertDialog show(Activity activity,JSONObject card,int portions,Write write,Runnable complete){String uid=new CloudSession(activity).account().optString("uid");if(uid.isEmpty()){AccountDialog.show(activity,complete);return null;}LinearLayout content=Ui.column(activity);content.setTag("plan.compose");content.setPadding(Ui.dp(activity,28),Ui.dp(activity,26),Ui.dp(activity,28),Ui.dp(activity,24));content.addView(KitViews.text(activity,"Wann möchtest du das kochen?",30,Ui.INK,true));TextView title=KitViews.text(activity,card.optString("title")+" · "+portions+" Portionen",24,Ui.INK,false);title.setPadding(0,Ui.dp(activity,18),0,Ui.dp(activity,20));content.addView(title);String[] date={java.time.LocalDate.now().toString()};boolean[] busy={false};int[] generation={0};PlanDayStrip days=new PlanDayStrip(activity,date[0],day->{if(!busy[0])date[0]=day;});content.addView(days);TextView status=KitViews.text(activity,"Erscheint im selben Konto auch auf deinem Handy.",21,Ui.MUTED,false);status.setTag("plan.status");status.setPadding(0,Ui.dp(activity,20),0,Ui.dp(activity,20));content.addView(status);LinearLayout actions=new LinearLayout(activity);Button close=Ui.button(activity,"Zurück",v->{}),send=Ui.button(activity,"Einplanen",v->{});send.setTag("plan.submit");close.setTag("plan.close");send.setTextSize(25);close.setTextSize(25);close.setBackground(KitViews.shape(activity,Ui.SOFT,40,0));send.setBackground(KitViews.shape(activity,Ui.ACCENT,40,0));send.setTextColor(0xff171716);actions.addView(close,new LinearLayout.LayoutParams(0,Ui.dp(activity,78),1));LinearLayout.LayoutParams primary=new LinearLayout.LayoutParams(0,Ui.dp(activity,78),2);primary.leftMargin=Ui.dp(activity,12);actions.addView(send,primary);content.addView(actions);AlertDialog dialog=new AlertDialog.Builder(activity).setView(content).create();dialog.show();new FrostedPanel(activity).apply(content,false,28);RotaryDialogs.bind(activity,dialog);Handler main=new Handler(Looper.getMainLooper());close.setOnClickListener(v->dialog.dismiss());dialog.setOnDismissListener(d->main.removeCallbacksAndMessages(null));send.setOnClickListener(v->{if(busy[0])return;busy[0]=true;int request=++generation[0];send.setEnabled(false);days.setEnabled(false);send.setText("Wird eingeplant …");status.setText("Warte auf die Bestätigung deines gemeinsamen Kochplans …");String chosen=date[0];main.postDelayed(()->{if(dialog.isShowing()&&generation[0]==request&&busy[0]){busy[0]=false;send.setEnabled(true);send.setText("Bestätigung erneut prüfen");status.setText("Noch keine Bestätigung. Ein erneuter Versuch verwendet denselben Auftrag und legt keinen doppelten Eintrag an.");}},20000);new Thread(()->{try{write.add(new JSONObject(card.toString()),chosen,portions);main.post(()->{if(!dialog.isShowing()||generation[0]!=request||activity.isDestroyed()||!uid.equals(new CloudSession(activity).account().optString("uid")))return;Toast.makeText(activity,"Im Kochplan eingeplant",Toast.LENGTH_SHORT).show();dialog.dismiss();complete.run();});}catch(Exception error){main.post(()->{if(!dialog.isShowing()||generation[0]!=request||activity.isDestroyed()||!uid.equals(new CloudSession(activity).account().optString("uid")))return;busy[0]=false;send.setEnabled(true);send.setText("Erneut übertragen");status.setText(error.getMessage()==null?"Die Übertragung ist noch nicht bestätigt. Versuche es erneut.":error.getMessage());});}},"shared-plan-append").start();});return dialog;}
 private SharedPlanDialog(){}
}
